def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = me.count('D')

    # Endgame: exploit cooperators, avoid being exploited by defectors.
    if n >= 96:
        if opp_c >= n * 0.7:
            return 'D'
        if opp_d >= n * 0.5:
            return 'D'
        return 'C'

    # Persistent defector: retaliate.
    if n >= 6 and opp_d >= n - 2:
        return 'D'

    # Persistent cooperator: cooperate mostly, probe occasionally.
    if n >= 6 and opp_d == 0:
        if n > 25 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Very cooperative opponent: mild probing.
    if n >= 12 and opp_d <= max(1, n // 10):
        if rng.random() < 0.08:
            return 'D'
        return 'C'
    if n >= 12 and opp_d <= n // 4:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent defected last round.
    if last_opp == 'D':
        # If we already defected last round, mostly keep defecting to punish,
        # but try to restore cooperation if opponent was previously nice.
        if last_me == 'D':
            if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
                return 'C'
            if opp_d * 3 <= n:
                return 'C'
            return 'D'
        # We cooperated, opponent defected. Retaliate strongly.
        # If opponent has a strong cooperative history and this is isolated,
        # sometimes forgive to restore mutual cooperation.
        if opp_d <= max(1, n // 12) and n >= 6:
            if rng.random() < 0.5:
                return 'C'
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'
        return 'D' if rng.random() < 0.9 else 'C'

    # Opponent cooperated. If we're in a defection cycle, return to cooperation.
    if last_me == 'D':
        if opp_d * 3 <= n:
            return 'C'
        if my_d > opp_d:
            return 'C'
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    # Both cooperated. Occasionally probe while keeping cooperation dominant.
    if n >= 20 and opp_d == 0 and rng.random() < 0.03:
        return 'D'
    return 'C'
